class Solution {
    vector<vector<int>> graph;
    vector<int> state;
    int destination;

    bool dfs(int node) {
        if (graph[node].empty()) {
            return node == destination;
        }
        if (state[node] == 1) {
            return false;
        }
        if (state[node] == 2) {
            return true;
        }
        state[node] = 1;
        for (int next : graph[node]) {
            if (!dfs(next)) {
                return false;
            }
        }
        state[node] = 2;
        return true;
    }

public:
    bool leadsToDestination(int n, vector<vector<int>>& edges,
                            int source, int dest) {
        graph.assign(n, {});
        state.assign(n, 0);
        destination = dest;
        for (const auto& edge : edges) {
            graph[edge[0]].push_back(edge[1]);
        }
        return dfs(source);
    }
};
